#include <stdio.h>

/* 扩展欧几里得: 求 ax + by = gcd(a, b) 的一组整数解, 并用它计算模逆元
   输入: a m
   输出: gcd(a,m)、系数 x y, 以及 a 模 m 的逆元(存在时)
   示例: 17 43 -> gcd=1, 17*(-5)+43*2=1, 逆元 = 38 */
long long exgcd(long long a, long long b, long long *x, long long *y) {
    if (b == 0) { *x = 1; *y = 0; return a; }   /* 基础情形: gcd(a,0)=a */
    long long x1, y1;
    long long g = exgcd(b, a % b, &x1, &y1);
    *x = y1;                                    /* 回溯: x = y' */
    *y = x1 - (a / b) * y1;                     /* y = x' - (a/b)*y' */
    return g;
}

int main(void) {
    long long a, m, x, y;
    printf("输入 a m: ");
    if (scanf("%lld %lld", &a, &m) != 2 || a < 0 || m <= 0) {
        printf("输入无效!\n"); return 1;
    }
    long long g = exgcd(a, m, &x, &y);
    printf("gcd(%lld, %lld) = %lld\n", a, m, g);
    printf("%lld * %lld + %lld * %lld = %lld\n", a, x, m, y, g);
    if (g == 1) {
        long long inv = (x % m + m) % m;        /* 逆元须为非负 */
        printf("%lld 模 %lld 的逆元 = %lld (验证 %lld*%lld mod %lld = 1)\n",
               a, m, inv, a, inv, m);
    } else {
        printf("%lld 模 %lld 不存在逆元 (gcd != 1)\n", a, m);
    }
    return 0;
}

#include <stdio.h>

/* 快速幂(二进制幂): O(log n) 次乘法计算 a^n mod m
   输入: a n m
   输出: a^n mod m
   示例: 3 50 7 -> 2 (因 3^6 ≡ 1 mod 7, 3^50 ≡ 3^2 = 9 ≡ 2) */
long long modpow(long long a, long long n, long long m) {
    long long res = 1 % m;              /* n = 0 时返回 1 mod m */
    a %= m;
    while (n > 0) {
        if (n & 1) res = res * a % m;   /* 二进制位为 1: 乘入当前 base */
        a = a * a % m;                  /* base 逐位平方 */
        n >>= 1;
    }
    return res;
}

int main(void) {
    long long a, n, m;
    printf("输入 a n m (计算 a^n mod m): ");
    if (scanf("%lld %lld %lld", &a, &n, &m) != 3 || m <= 0) {
        printf("输入无效!\n"); return 1;
    }
    printf("%lld^%lld mod %lld = %lld\n", a, n, m, modpow(a, n, m));
    return 0;
}

