/* 素数筛综合演示: 埃氏筛 O(n log log n)、线性筛 O(n)、区间素数筛 [L, R]
   输入: n L R  (2 <= n <= 10^7; 1 <= L <= R <= 10^12, R-L <= 10^6)
   输出: [2,n] 内素数个数(两种筛法), [L,R] 内素数个数与前 40 个 */
#define MAXN 10000001
#define MAXP 800000
static bool comp[MAXN];                  /* 合数标记 */
static int primes[MAXP], pcnt;

static int eratosthenes(int n, int *out) {   /* 返回素数个数, 素数写入 out */
    memset(comp, 0, sizeof(comp));
    int cnt = 0;
    for (int p = 2; p <= n; p++) {
        if (!comp[p]) {
            if (out) out[cnt] = p;
            cnt++;
            if ((long long)p * p <= n)               /* 从 p^2 开始标记 */
                for (long long j = (long long)p * p; j <= n; j += p)
                    comp[j] = true;
        }
    }
    return cnt;
}

static int linear_sieve(int n) {                     /* 每个合数只被最小质因子标记 */
    memset(comp, 0, sizeof(comp));
    pcnt = 0;
    for (int i = 2; i <= n; i++) {
        if (!comp[i]) primes[pcnt++] = i;
        for (int j = 0; j < pcnt; j++) {
            long long x = (long long)i * primes[j];
            if (x > n) break;
            comp[x] = true;
            if (i % primes[j] == 0) break;           /* 关键: 保证最小质因子 */
        }
    }
    return pcnt;
}

int main(void) {
    long long n, L, R;
    printf("输入 n L R (2<=n<=10^7, 1<=L<=R<=10^12, R-L<=10^6): ");
    if (scanf("%lld %lld %lld", &n, &L, &R) != 3 || n < 2 || n > MAXN - 1 ||
        L < 1 || R > 1000000000000LL || R - L > 1000000) {
        printf("输入无效!\n"); return 1;
    }
    printf("埃氏筛: [2, %lld] 素数个数 = %d\n", n, eratosthenes((int)n, NULL));
    printf("线性筛: [2, %lld] 素数个数 = %d\n", n, linear_sieve((int)n));
    /* 区间素数: 用 <= sqrt(R) 的素数标记 [L, R] 内合数 */
    static bool bad[1000001];
    memset(bad, 0, sizeof(bad));
    int sq = (int)sqrt((double)R);
    int bc = eratosthenes(sq, primes);               /* 复用 primes 存小素数 */
    for (int i = 0; i < bc; i++) {
        long long p = primes[i];
        long long start = p * p;
        long long m = ((L + p - 1) / p) * p;         /* 区间内第一个 p 的倍数 */
        if (m > start) start = m;
        for (long long x = start; x <= R; x += p)
            bad[x - L] = true;                       /* 偏移下标 */
    }
    if (L <= 1 && R >= 1) bad[1 - L] = true;         /* 1 不是素数 */
    int cnt3 = 0, shown = 0;
    printf("[%lld, %lld] 内素数: ", L, R);
    for (long long x = L; x <= R; x++) {
        if (!bad[x - L]) {
            cnt3++;
            if (shown < 40) { printf("%lld ", x); shown++; }
        }
    }
    if (cnt3 > 40) printf("... ");
    printf("\n区间素数个数 = %d\n", cnt3);
    return 0;
}

# 素数筛综合演示: 埃氏筛、线性筛计数, 以及区间素数筛 [L, R]
import math
import sys

def eratosthenes(limit):
    # 埃氏筛: 返回 [2, limit] 内素数列表
    is_p = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        is_p[0] = 0
    if limit >= 1:
        is_p[1] = 0
    for i in range(2, int(math.isqrt(limit)) + 1):
        if is_p[i]:
            # 从 i^2 开始标记 i 的倍数
            is_p[i * i: limit + 1: i] = b"\x00" * ((limit - i * i) // i + 1)
    return [i for i in range(2, limit + 1) if is_p[i]]

def linear_sieve(limit):
    # 线性筛: 每个合数只被最小质因子标记一次, O(n)
    comp = bytearray(limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if not comp[i]:
            primes.append(i)
        for p in primes:
            x = i * p
            if x > limit:
                break
            comp[x] = 1
            if i % p == 0:
                break                   # 关键: 保证最小质因子标记
    return primes

data = list(map(int, sys.stdin.read().split()))
n, L, R = data[0], data[1], data[2]
print(f"埃氏筛: [2, {n}] 素数个数 = {len(eratosthenes(n))}")
print(f"线性筛: [2, {n}] 素数个数 = {len(linear_sieve(n))}")
# 区间素数: 筛 sqrt(R) 内素数, 再标记 [L, R] 内合数(偏移下标)
base = eratosthenes(int(math.isqrt(R)) + 1)
bad = bytearray(R - L + 1)
for p in base:
    start = max(p * p, ((L + p - 1) // p) * p)
    for x in range(start, R + 1, p):
        bad[x - L] = 1
if L <= 1 <= R:
    bad[1 - L] = 1                      # 1 不是素数
primes = [L + i for i in range(R - L + 1) if not bad[i]]
print(f"[{L}, {R}] 内素数:", primes[:40], ("..." if len(primes) > 40 else ""))
print(f"区间素数个数 = {len(primes)}")

#include <stdio.h>

/* 中国剩余定理: 两两互素模数的同余方程组, 构造解 x ≡ Σ a_i·M_i·t_i (mod M)
   输入: k, 之后 k 行 a_i m_i (模数两两互素)
   输出: M、解 x、逐式验证
   示例: 3 / 2 3 / 3 5 / 2 7 -> x = 23 (mod 105) */
long long exgcd(long long a, long long b, long long *x, long long *y) {
    if (b == 0) { *x = 1; *y = 0; return a; }
    long long x1, y1, g = exgcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

long long inv_mod(long long a, long long m) {   /* 模逆元, 要求 gcd(a, m) = 1 */
    long long x, y;
    exgcd(a, m, &x, &y);
    return (x % m + m) % m;
}

int main(void) {
    int k;
    long long a[20], m[20];
    printf("输入方程个数 k: ");
    if (scanf("%d", &k) != 1 || k < 1 || k > 20) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 行 a_i m_i (模数两两互素):\n", k);
    for (int i = 0; i < k; i++) scanf("%lld %lld", &a[i], &m[i]);
    long long M = 1;
    for (int i = 0; i < k; i++) M *= m[i];
    long long x = 0;
    for (int i = 0; i < k; i++) {
        long long Mi = M / m[i];
        long long ti = inv_mod(Mi % m[i], m[i]);   /* M_i 模 m_i 的逆元 */
        x = (x + (a[i] % M) * (Mi % M) % M * ti) % M;
    }
    printf("M = %lld, 解 x ≡ %lld (mod %lld)\n", M, x, M);
    for (int i = 0; i < k; i++)
        printf("验证: x mod %lld = %lld (期望 %lld)\n", m[i], x % m[i], a[i]);
    return 0;
}

#include <stdio.h>

/* RSA 公钥密码演示(小型素数, 仅教学): 密钥生成 + 加密 + 解密
   输入: p q e m (素数 p q, 加密指数 e, 明文 m < p*q)
   输出: n, phi, 私钥 d, 密文 c, 解密结果
   示例: 61 53 17 65 -> n=3233, phi=3120, d=2753, c=2790, 解密 65
   注意: 实际应用中 p, q 必须是 1024 位以上的大素数(如 n >= 2048 位),
         并配合 OAEP 填充, 这里仅演示算法流程! */
long long exgcd(long long a, long long b, long long *x, long long *y) {
    if (b == 0) { *x = 1; *y = 0; return a; }
    long long x1, y1, g = exgcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

long long modpow(long long a, long long n, long long m) {   /* 快速幂 O(log n) */
    long long res = 1 % m;
    a %= m;
    while (n > 0) {
        if (n & 1) res = res * a % m;
        a = a * a % m;
        n >>= 1;
    }
    return res;
}

int main(void) {
    long long p, q, e, m, x, y;
    printf("输入素数 p q, 加密指数 e, 明文 m: ");
    if (scanf("%lld %lld %lld %lld", &p, &q, &e, &m) != 4 || p < 2 || q < 2) {
        printf("输入无效!\n"); return 1;
    }
    long long n = p * q;
    long long phi = (p - 1) * (q - 1);
    long long g = exgcd(e, phi, &x, &y);
    if (g != 1) {
        printf("错误: gcd(e, phi) != 1, 私钥不存在, 请重选 e\n");
        return 1;
    }
    long long d = (x % phi + phi) % phi;        /* 私钥指数 */
    long long c = modpow(m, e, n);              /* 加密 */
    long long mm = modpow(c, d, n);             /* 解密 */
    printf("n = %lld, phi(n) = %lld\n", n, phi);
    printf("公钥 (e, n) = (%lld, %lld)\n", e, n);
    printf("私钥 (d, n) = (%lld, %lld)\n", d, n);
    printf("加密: c = %lld^%lld mod %lld = %lld\n", m, e, n, c);
    printf("解密: m = %lld^%lld mod %lld = %lld\n", c, d, n, mm);
    printf("%s\n", mm == m ? "验证通过: 解密恢复明文!" : "验证失败!");
    return 0;
}

